
const $=(s,r=document)=>r.querySelector(s),app=$('#app');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const oneLine=s=>String(s==null?'':s).replace(/[\r\n\u2028\u2029]+/g,' ').replace(/\s+/g,' ').trim();
document.addEventListener('click',e=>{const d=e.target.closest&&e.target.closest('.cl li>div');if(d)d.parentNode.classList.toggle('open')});
const shuf=a=>{a=[...a];for(let i=a.length;i>1;){const j=Math.random()*i--|0;[a[i],a[j]]=[a[j],a[i]]}return a};
const norm=s=>String(s).trim().toLowerCase(),clean=w=>w.toUpperCase().replace(/[^A-Z]/g,'');
let TTSU=null,TTSMSG=null;
const ttsNote=m=>{try{if(TTSMSG)TTSMSG.remove();TTSMSG=document.createElement('div');TTSMSG.id='ttsn';TTSMSG.setAttribute('role','status');TTSMSG.style.cssText='position:fixed;left:8px;right:8px;bottom:8px;z-index:99;background:#7a1f1f;color:#fff;padding:10px 12px;border-radius:12px;font:600 15px system-ui,sans-serif;text-align:center';TTSMSG.textContent=m;document.body.appendChild(TTSMSG);const n=TTSMSG;setTimeout(()=>{try{n.remove()}catch(e){}},6000)}catch(e){}};
const TTS=[{n:'Clear',d:'Standard voice, easy to follow',v:0,r:.85,p:1},{n:'Slow &amp; careful',d:'Extra slow for hard words',v:0,r:.6,p:1}];
let ttsIdx=-1;const tIdx=()=>{if(ttsIdx<0){let n=0;try{n=parseInt(sget('henrys_words_voice'),10)}catch(e){}ttsIdx=n>=0&&n<TTS.length?n:0}return ttsIdx};
let ttsRate=null;const tRate=()=>{if(ttsRate==null){let n=NaN;try{n=parseFloat(sget('henrys_words_rate'))}catch(e){}ttsRate=n>=.3&&n<=1.5?n:0}return ttsRate||0};
const enVoices=()=>{try{const sc=x=>(/en[-_]US/i.test(x.lang)?2:0)+(/samantha|google us|aria|jenny|natural|enhanced|premium|daniel|karen|moira/i.test(x.name)?1:0);
 const seen=new Set();return (speechSynthesis.getVoices()||[]).filter(x=>/^en([-_]|$)/i.test(x.lang||'')).sort((a,b)=>sc(b)-sc(a)).filter(x=>!seen.has(x.name)&&seen.add(x.name))}catch(e){return[]}};
const voiceFor=o=>{const v=enVoices();return v.length?v[o.v%v.length]:null};
try{speechSynthesis.getVoices()}catch(e){}
const say=(t,o)=>{
 if(!t)return;
 if(!window.speechSynthesis||typeof SpeechSynthesisUtterance=='undefined')return ttsNote('Spoken words are not available in this browser. Try Safari, Chrome or Edge.');
 o=o||TTS[tIdx()];
 const go=()=>{try{const u=new SpeechSynthesisUtterance(String(t));const vo=voiceFor(o);if(vo){u.voice=vo;u.lang=vo.lang}else u.lang='en-US';u.rate=tRate()||o.r;u.pitch=o.p;u.volume=1;
  u.onerror=e=>{if(e&&(e.error=='interrupted'||e.error=='canceled'))return;ttsNote(e&&e.error=='not-allowed'?'Sound is blocked. Tap the speaker button again, and check the volume and silent switch.':'Could not speak. Check the volume, then tap the speaker again.')};
  TTSU=u;speechSynthesis.speak(u);try{speechSynthesis.resume()}catch(e){}}catch(e){ttsNote('Could not speak. Check the volume, then tap the speaker again.')}};
 try{if(speechSynthesis.speaking||speechSynthesis.pending){speechSynthesis.cancel();setTimeout(go,80)}else go()}catch(e){go()}};
function voicePanel(){
 const old=document.getElementById('vp');if(old){old.remove();return}
 const d=document.createElement('div');d.id='vp';d.setAttribute('role','dialog');d.setAttribute('aria-label','Choose a voice');
 const draw=()=>{const vs=enVoices(),ci=tIdx(),r=tRate()||TTS[ci].r;d.innerHTML=`<div class="card vpc"><h2>🗣 Choose a voice</h2><p class="lbl">Tap one to hear it. The one you pick is used for every speaker button.${vs.length?'':' (This device has only its standard voice.)'}</p>${TTS.map((o,i)=>{const vo=voiceFor(o);return `<button class="vopt${i==ci?' on':''}" data-i="${i}" aria-pressed="${i==ci}"><div><b>${o.n}</b><small>${o.d}${vo?' · '+esc(vo.name):''}</small></div><span>${i==ci?'✓':'🔊'}</span></button>`}).join('')}<label class="lbl" for="vr" style="display:block;margin-top:14px">Speed: <b id="vrv">${r.toFixed(2)}×</b> <small>(drag to slow down or speed up)</small></label><div class="vsl"><span aria-hidden="true">🐢</span><input id="vr" type="range" min="0.4" max="1.4" step="0.05" value="${r}" aria-label="Voice speed"><span aria-hidden="true">🐇</span></div><button class="btn" id="vx">Done</button></div>`;
  d.querySelectorAll('.vopt').forEach(b=>b.onclick=()=>{ttsIdx=+b.dataset.i;ttsRate=TTS[ttsIdx].r;sset('henrys_words_voice',String(ttsIdx));sset('henrys_words_rate',String(ttsRate));say('Spell the word: journey.',TTS[ttsIdx]);draw()});
  const vr=$('#vr',d);vr.oninput=()=>{ttsRate=parseFloat(vr.value)||.85;$('#vrv',d).textContent=ttsRate.toFixed(2)+'×'};
  vr.onchange=()=>{ttsRate=parseFloat(vr.value)||.85;sset('henrys_words_rate',String(ttsRate));say('Spell the word: journey.')};
  $('#vx',d).onclick=()=>d.remove()};
 d.onclick=e=>{if(e.target===d)d.remove()};draw();document.body.appendChild(d)}
const blank=x=>{if(!x.s)return null;const b=x.s.replace(new RegExp(x.w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),'_____');return b==x.s?null:b};
