/* ---- storage: localStorage with an in-memory fallback so sign-in still works if the browser blocks storage ---- */
const MEM={};
const canStore=(()=>{try{localStorage.setItem('hw_t','1');localStorage.removeItem('hw_t');return true}catch(e){return false}})();
const sget=k=>{try{const v=localStorage.getItem(k);if(v!==null)return v}catch(e){}return k in MEM?MEM[k]:null};
const sset=(k,v)=>{MEM[k]=v;try{localStorage.setItem(k,v)}catch(e){}};
const hash=s=>{let h=5381;for(const c of 'hw1'+s)h=((h<<5)+h+c.charCodeAt(0))>>>0;return 'henrys_words_'+h};
/* passwords ignore capitals, extra spaces and keyboard autocorrect trailing spaces */
const pwNorm=s=>(s.normalize?s.normalize('NFKC'):s).trim().replace(/\s+/g,' ').toLowerCase();
const PROF=/^henrys_words_\d+$/;
const profiles=()=>{const s=new Set(Object.keys(MEM).filter(k=>PROF.test(k)));try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&PROF.test(k))s.add(k)}}catch(e){}return[...s]};
const load=()=>{try{const v=JSON.parse(sget(key));return Array.isArray(v)?v.map(x=>x&&typeof x.d=='string'?Object.assign({},x,{d:oneLine(x.d)}):x):[]}catch(e){return[]}};
/* basic mode shows only: Words, Flashcards, Word Search, Quiz, Test. The ! button shows everything. */
