 v.innerHTML=`<div class="card"><h2>📋 Test</h2><p class="lbl">Practice with</p>${poolChips()}<p class="lbl">How many words?</p>${countChips()}<p class="lbl">Listen only: you see just speaker buttons. One says the word, one uses it in a sentence, one gives the meaning. Type what you hear. Answers show at the end.</p><button class="btn" id="st" ${P.length?'':'disabled'}>Start test (${n} words)</button></div>`;
