 /* online lookup (free dictionaryapi.dev) */
 const out=$('#lkr'),lk=$('#lk');
 const show=d=>{const e=d[0],ph=e.phonetic||(e.phonetics||[]).map(p=>p.text).find(Boolean)||'';
  const ms=(e.meanings||[]).map(m=>{const ds=(m.definitions||[]).slice(0,3),sy=[...new Set([...(m.synonyms||[]),...ds.flatMap(x=>x.synonyms||[])])].slice(0,6),an=(m.antonyms||[]).slice(0,4);
   return `<b class="p">${esc(m.partOfSpeech||'')}</b><ol>${ds.map(x=>`<li>${esc(oneLine(x.definition||''))}${x.example?`<br><i>${esc(x.example)}</i>`:''}</li>`).join('')}</ol>${sy.length?`<p class="syn">Similar: ${sy.map(esc).join(', ')}</p>`:''}${an.length?`<p class="syn">Opposite: ${an.map(esc).join(', ')}</p>`:''}`}).join('');
  out.innerHTML=`<p class="big">${esc(e.word)} <small class="lbl">${esc(ph)}</small></p><p><button class="btn alt sm" id="lh">🔊 Hear it</button> <button class="btn sm" id="lad">＋ Add to my words</button></p>${ms}`;
  $('#lh').onclick=()=>say(e.word);
  $('#lad').onclick=()=>{const m=(e.meanings||[])[0]||{},df=(m.definitions||[])[0]||{},pk=Object.keys(POSN).find(k=>POSN[k]==m.partOfSpeech)||'';
   prefill={w:e.word,d:defText(df.definition||''),s:df.example?sentText(df.example):'',p:pk};edit=-1;tab='words';main();scrollTo(0,0)}};
 const look=async()=>{const w=lk.value.trim().toLowerCase();if(!w)return;out.innerHTML='<p class="lbl">Looking it up…</p>';
  try{const r=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(w));
   if(r.status==404)return out.innerHTML=`<p>No entry found for “${esc(w)}”. Check the spelling.</p>`;
   if(!r.ok)throw new Error('http '+r.status);show(await r.json())}
  catch(e){out.innerHTML='<p class="fb no">Couldn’t reach the online dictionary. Check your internet connection. The built-in dictionary below works without internet.</p>'}};
 $('#lkb').onclick=look;lk.onkeydown=e=>{if(e.key=='Enter'){e.preventDefault();look()}};
